public class UnionFind&lt;T&gt; {
    public Node&lt;T&gt; makeNode(T v) {
        return new Node&lt;T&gt;(v);
    }

    public Node&lt;T&gt; find(Node&lt;T&gt; node) {
        while (node != node.parent) {
            node = node.parent;
        }
        return node;
    }

    public void union(Node&lt;T&gt; x, Node&lt;T&gt; y) {
        Node&lt;T&gt; nx = find(x);
        Node&lt;T&gt; ny = find(y);

        if (nx == ny) return;

        if (nx.rank &gt; ny.rank) {
            ny.parent = nx;
        } else if (nx.rank &lt; ny.rank) {
            nx.parent = ny;
        } else {
            ny.parent = nx;
            nx.rank++;
        }
    }
}


