Basic version
class Solution {

    // Dijkstra's algorithm - O(n^2) version
    public int networkDelayTime(int[][] times, int n, int k) {
        // construct the graph using the input edges
        Map&lt;Integer, Map&lt;Integer, Integer&gt;&gt; graph = new HashMap&lt;&gt;();
        for (int[] t : times) {
            graph.putIfAbsent(t[0], new HashMap&lt;&gt;());
            graph.get(t[0]).put(t[1], t[2]);
        }

        // shortest time to reach every node from the node k
        int[] minTime = new int[n + 1];
        Arrays.fill(minTime, Integer.MAX_VALUE);
        minTime[k] = 0;

        // flag array to track visit status
        boolean[] visited = new boolean[n + 1];

        // Dijkstra's algorithm
        int res = 0;
        for (int i = 0; i &lt; n; i++) {
            // identify the node with the shortest time
            int next = -1;
            for (int j = 1; j &lt;= n; j++) {
                if (visited[j]) continue;
                if (next &lt; 0 || minTime[j] &lt; minTime[next]) next = j;
            }

            // mark the node as visit
            visited[next] = true;
            res = minTime[next];
            if (res == Integer.MAX_VALUE) return -1;

            // update the time array
            if (graph.containsKey(next)) {
                Map&lt;Integer, Integer&gt; connections = graph.get(next);
                for (int t : connections.keySet()) {
                    int temp = minTime[next] + connections.get(t);
                    if (temp &lt; minTime[t]) {
                        minTime[t] = temp;
                    }
                }
            }
        }
        return res;
    }
}


Optimized version

class Solution {
    // 07/30/2024 - Dijkstra's algorithm with priority queue
    public int networkDelayTime(int[][] times, int n, int k) {
        // here we construct the graph first
        // format: source -&gt; target : weight
        Map&lt;Integer, Map&lt;Integer, Integer&gt;&gt; graph = new HashMap&lt;&gt;();
        for (int[] t : times) {
            graph.putIfAbsent(t[0], new HashMap&lt;&gt;());
            graph.get(t[0]).put(t[1], t[2]);
        }

        // we track if a note is visited or not, once visited, its shortest distance
        // to the source node cannot change.
        boolean[] visited = new boolean[n + 1];
        int[] minTime = new int[n + 1];
        Arrays.fill(minTime, Integer.MAX_VALUE);

        // we use a priority queue to track the edges to visit next
        // format: node id: distance to the source node
        PriorityQueue&lt;int[]&gt; que = new PriorityQueue&lt;&gt;((a, b) -&gt; Integer.compare(a[1], b[1]));
        que.add(new int[]{k, 0});

        int res = -1;
        int count = 0;
        while (!que.isEmpty()) {
            int[] edge = que.poll();
            int curr = edge[0], time = edge[1];
            if (visited[curr]) continue;

            visited[curr] = true;
            minTime[curr] = time;
            res = time;
            count++;

            if (graph.containsKey(curr)) {
                Map&lt;Integer, Integer&gt; connections = graph.get(curr);
                for (int next : connections.keySet()) {
                    int weight = connections.get(next);
                    if (time + weight &lt; minTime[next]) {
                        que.offer(new int[]{next, time + weight});
                    }
                }
            }
        }
        return count == n ? res : -1;
    }
}

Bellman-Ford Algorithm
class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        int[] minTime = new int[n + 1];
        Arrays.fill(minTime, Integer.MAX_VALUE);
        minTime[k] = 0;

        for (int i = 1; i &lt; n; i++) {
            for (int[] e : times) {
                int src = e[0], dst = e[1], w = e[2];
                if (minTime[src] != Integer.MAX_VALUE && minTime[src] + w &lt; minTime[dst]) {
                    minTime[dst] = minTime[src] + w;
                }
            }
        }
        int res = -1;
        for (int i = 1; i &lt;= n; i++) {
            res = Math.max(res, minTime[i]);
        }
        return res == Integer.MAX_VALUE ? -1 : res;
    }
}

Solution
The key idea in the solution is to recognize the fact that once a car catches up with another car, it cannot pass and must drive at the same speed, thus form a fleet. If the target is far away, all the cars will eventually merge into several clusters, with each cluster traveling at the same speed.
Given limited distance to the target, a car behind might not be able to catch up with another car ahead of it. Note that the time taken for a car i at position position[i] to reach the target at speed speed[i] is:
timeToTarget = (target - position[i]) / speed[i]
For any two cars i and j with position[i] &gt; position[j], car j can catchup with car i if timeToTarget[j] &lt; timeToTarget[i].
Recognizing this, we could sort all the cars in decreasing order of their current positions and then check if a car could catch up with the car right ahead of it.
class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        // sort cars in decreasing order of their current positions
        int n = position.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i &lt; n; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, (i, j) -&gt; position[j] - position[i]);

        // merge cars into fleet
        int res = 0;
        double prev = 0;
        for (int i : indices) {
            double timeToTarget = (double) (target - position[i]) / speed[i];
            if (timeToTarget &gt; prev) {
                res++;
                prev = timeToTarget;
            }
        }
        return res;
    }
}

Prim’s Algorithm
class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length;
        Set&lt;Integer&gt; mst = new HashSet&lt;&gt;();
        int[] dist = new int[n];

        // pick starting node
        mst.add(0);
        for (int i = 1; i &lt; n; i++) {
            dist[i] = calDist(points, 0, i);
        }

        // keep adding new nodes
        int res = 0;
        while (mst.size() != n) {
            // pick the node with the shortest distance to the nodes in the current mst
            int next = -1;
            for (int i = 0; i &lt; n; i++) {
                if (mst.contains(i)) continue;
                if (next &lt; 0 || dist[next] &gt; dist[i]) next = i;
            }

            // add the new node to the mst
            mst.add(next);
            res += dist[next];

            // update the distances
            for (int i = 0; i &lt; n; i++) {
                if (mst.contains(i)) continue;
                int newDist = calDist(points, next, i);
                if (newDist &lt; dist[i]) dist[i] = newDist;
            }

        }
        return res;
    }

    private int calDist(int[][] points, int x, int y) {
        return Math.abs(points[x][0] - points[y][0]) + Math.abs(points[x][1] - points[y][1]);
    }
}

