class Solution {
    public int minCostConnectPoints(int[][] points) {
        if (points.length &lt; 2) return 0;

        List&lt;Edge&gt; edges = new ArrayList&lt;&gt;();
        int n = points.length;
        for (int i = 0; i &lt; n; i++) {
            for (int j = i + 1; j &lt; n; j++) {
                int dist = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
                edges.add(new Edge(i, j, dist));
            }
        }
        edges.sort((a, b) -&gt; Integer.compare(a.dist, b.dist));

        // define union-find dsa
        Map&lt;Integer, Node&gt; map = new HashMap&lt;&gt;();
        for (int i = 0; i &lt; n; i++) {
            map.put(i, new Node());
        }
        UnionFind uf = new UnionFind();

        Set&lt;Edge&gt; mst = new HashSet&lt;&gt;();
        int eIdx = 0;
        int res = 0;
        while (mst.size() != n - 1) {
            // pick the edge with the shortest distance
            Edge curr = edges.get(eIdx++);

            // check if adding the edge to the mst will create a cycle
            boolean success = uf.union(map.get(curr.start), map.get(curr.end));
            if (success) {
                mst.add(curr);
                res += curr.dist;
            }
        }
        return res;
    }

